  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    if (c === 10) { out.push(t.slice(start, i)); start = i + 1; run = 0; } else if (json && c === 110 && run % 2 === 1) { out.push(t.slice(start, i - 1)); start = i + 1; run = 0; } else run = c === 92 ? run + 1 : 0;
  }
