  for (const i of fails) { take(i); take(i - 1); take(i + 1); }
  for (let i = 0; i < Math.min(n, DIGEST_FIRST); i++) take(i);
  for (let i = n - 1; i >= Math.max(0, n - DIGEST_LAST); i--) take(i);
  for (let i = 0; i < n; i++) if (runOf[i]?.[0] === i) take(i);
