// holding its tailnet address, so no command runs on another Spark), and linger and Funnel with the route check
// (checkRoute, at start and every 60 s). Each look only reads. What they found is kept in memory (a restart looks again
// within a minute), and waysInNeeds turns it into needs-you lines (20-needs.mjs): a key within 14 days of expiring, or
// expired; linger off; Funnel off while funnel-seen.json says it was on. An answer that can't be read, or none for three
// looks, is "couldn't check", never silence. A line's key is its kind and Spark (never a date), so the needs-me line
// (20-tell.mjs) tells it once. Disk space is the status loop's line in 20-needs.mjs: the state folder and the journal sit
// under the home folder whose free space worker.py reports. The GitHub token isn't watched here: its expiry is known only
// by asking GitHub. (docs/rules/R49.md)
const KEY_SOON_MS = 14 * 86400000;
// How often the route check and Tailscale's status are read: every 60 s (tests shorten it, only under ALL_LOCAL).
const ROUTE_MS = ALL_LOCAL && Number(process.env.SPARK_CONSOLE_ROUTE_MS) > 0 ? Number(process.env.SPARK_CONSOLE_ROUTE_MS) : 60000;
// No answer for three looks is "couldn't check"; one look waits 10 s at most.
const LOOK_STALE_MS = 3 * ROUTE_MS + 10000, LOOK_WAIT_MS = 10000;
const FUNNEL_SEEN = `${STATE_DIR}/funnel-seen.json`;
const WAYS_WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const WAYS_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const waysDay = t => { const d = new Date(t); return `${WAYS_WEEKDAYS[d.getDay()]} ${d.getDate()} ${WAYS_MONTHS[d.getMonth()]}`; };
// The last readable answers and when they came (keysAt, lingerAt); a miss is the latest answer, unreadable.
const waysIn = { from: Date.now(), keys: null, keysAt: 0, keysMiss: false, linger: null, lingerAt: 0, lingerMiss: false, lingerBusy: false };

// Tailscale's status, as refreshBlocked read it: each Spark's key expiry (none: expiry is off for it) and whether
// Tailscale says it has expired, with the machine's name as Tailscale's admin page shows it (a plain name, or none).
function noteTailnet(code, out) {
  let st = null;
  try { st = code === 0 ? JSON.parse(out) : null; } catch {}
  if (!st || typeof st !== 'object' || !st.Self || typeof st.Self !== 'object') { waysIn.keysMiss = true; return; }
  const peers = Object.values(st.Peer && typeof st.Peer === 'object' ? st.Peer : {}).filter(p => p && typeof p === 'object'), keys = {}, ssh = {};
  for (const n of NODES) {
    const p = n.host === 'local' ? st.Self : peers.find(x => Array.isArray(x.TailscaleIPs) && x.TailscaleIPs.some(ip => ip && (ip === n.ip || ip === n.host)));
    if (!p) continue;
    const t = Date.parse(typeof p.KeyExpiry === 'string' ? p.KeyExpiry : ''), name = [String(p.DNSName || '').split('.')[0], p.HostName].find(x => /^[a-z0-9][a-z0-9-]{0,62}$/i.test(x || ''));
    keys[n.id] = { expires: Number.isFinite(t) ? t : null, expired: p.Expired === true, machine: name || null };
    // (whether that Spark advertises Tailscale SSH: its entry carries host keys for it; the ladder asks while one does,
    // 21-ladder.mjs. "Off" only for this machine or a peer that is online now; an offline one, or a Spark not in the
    // answer, is null or no entry here: "can't tell", never "off".)
    ssh[n.id] = Array.isArray(p.sshHostKeys) && p.sshHostKeys.length > 0 ? true : p === st.Self || p.Online === true ? false : null;
  }
  Object.assign(waysIn, { keys, ssh, keysAt: Date.now(), keysMiss: false });
}

// Linger for the console's own user on Spark 2, read as the installer reads it. One look at a time.
function lookLinger() {
  const hub = NODES.find(n => n.host === 'local');
  if (!hub || waysIn.lingerBusy) return;
  waysIn.lingerBusy = true;
  let out = '';
  const child = spawnOn(hub, { command: `loginctl show-user ${Number(process.getuid?.() ?? -1)} -p Linger --value` });
  const timer = setTimeout(() => child.kill('SIGKILL'), LOOK_WAIT_MS);
  child.stdout.on('data', d => { out += d; });
  child.stderr.on('data', () => {});
  child.on('error', () => {});
  child.on('close', code => {
    clearTimeout(timer);
    waysIn.lingerBusy = false;
    const v = code === 0 ? out.trim() : '';
    if (v === 'yes' || v === 'no') Object.assign(waysIn, { linger: v === 'yes', lingerAt: Date.now(), lingerMiss: false });
    else waysIn.lingerMiss = true;
  });
}

// The console's record that Funnel should be on: written the first time the route check sees Funnel on for the main
// address. Only the owner's `deploy/open-to-internet.sh --undo` (closing it on purpose) removes it.
function noteFunnel() {
  if (funnelOn !== true || existsSync(FUNNEL_SEEN)) return;
  try { writePrivate(FUNNEL_SEEN, { seenOnAt: new Date().toISOString() }); } catch {}
}

// The needs-you lines (openProblems, 20-needs.mjs). Each is tried by itself.
function waysInNeeds(add, here) {
  const now = Date.now(), stale = at => now - (at || waysIn.from) > LOOK_STALE_MS;
  const keyLines = () => {
    for (const n of NODES) {
      const k = waysIn.keys?.[n.id], name = sparkName(n), hub = n.host === 'local';
      if (!k) continue;
      const gone = k.expired || (k.expires !== null && k.expires <= now);
      if (!gone && (k.expires === null || k.expires - now > KEY_SOON_MS)) continue;
      const machine = k.machine || name, cut = hub ? 'only Telegram reaches Spark Console' : `Spark Console can’t reach ${name}`;
      if (gone) add(`tailscale-key:${n.id}`, `${name}’s Tailscale key expired${k.expires !== null ? ` on ${waysDay(k.expires)}` : ''}, so ${cut}. To fix it, sign in to Tailscale again on ${name}, then turn off key expiry in Tailscale’s admin page (Machines → ${machine}).`);
      else {
        const days = Math.ceil((k.expires - now) / 86400000);
        add(`tailscale-key:${n.id}`, `${name}’s Tailscale key expires in ${days} day${days === 1 ? '' : 's'}, on ${waysDay(k.expires)}. After that, ${cut}. Before then: Tailscale’s admin page → Machines → ${machine} → Disable key expiry.`);
      }
    }
  };
  const tries = [
    keyLines,
    () => { if (waysIn.keysMiss || stale(waysIn.keysAt)) add('tailscale-unread', `Spark Console couldn’t read Tailscale’s state on ${here}, so it can’t warn before a Tailscale key expires. Check that Tailscale is running there: tailscale status`); },
    () => { if (waysIn.linger === false) add('linger', `Spark Console stops when you log out of ${here}, and after a restart it stays off until you log in. To keep it running, run this once on ${here}: sudo loginctl enable-linger $USER`); },
    () => { if (waysIn.lingerMiss || stale(waysIn.lingerAt)) add('linger-unread', `Spark Console couldn’t check whether it starts by itself after ${here} restarts. Check on ${here}: loginctl show-user $USER -p Linger`); },
    () => { if (funnelOn === false && existsSync(FUNNEL_SEEN)) add('funnel', 'Funnel is off, so Spark Console can’t be reached from the internet: only devices with Tailscale on get in. To open it again: bash spark-console/deploy/open-to-internet.sh. Closed on purpose? Run it with --undo and this line goes.'); },
  ];
  for (const f of tries) { try { f(); } catch {} }
}
/* ───────── the owner's words: /status, /pause, /restart sparkie, /stop, /undo, /undo update, /help (round two, 2026-11-11) ───────── */
// Area: safety        Rules: R34        Tests: words.test.mjs
// Owns: none
// Timers: none        Wakes: none
// Typed as the whole message in the owner's own page chat, they're answered by code before any model call, so they work
// with Sparkie's model down or stuck (docs/analysis-2026-11-11/10-round-two-report.md, item 1; contract 8.13). They are
// not tools: no agent, no /mcp or /v1, no carry-on turn. They can only look, pause agents' changes, bring back the
// brain's own container (restart it, or start it again when it is stopped or gone: the same container, or the saved
// setup; never another model), end Sparkie's answer in that chat (/stop), put back its last change (/undo) or go back a
// build, or put back the newest change made inside the lock-out net (/putback, 21-net.mjs). /undo and /undo update are
// the words that run an action (undo_last_change, also while changes are paused;
// undo_update, through runAction as the page, so that action's own guard decides, R31). In the paired Telegram chat
// (21-telegram.mjs) /status, /pause, /restart sparkie, /stop, /undo and /help work too; /undo update never does there. Resuming is never a word (it needs the passkey, or the file by hand). On the page each answer
// is saved as one Spark Console notice quoting the word, so Sparkie later reads it as data.
const OWNER_WORDS = ['/status', '/pause', '/restart sparkie', '/stop', '/undo', '/undo update', '/allowed', '/putback', '/help'];
// The whole message, trimmed and lowercased ("/restart_sparkie" too); "/pause now" or "please /pause" is not a word.
function ownerWord(text) {
  const t = String(text).trim().toLowerCase().replace(/_/g, ' ');
  // (/allowed off 2, /allowed off all: 21-ahead.mjs)
  return t.length <= 40 && (OWNER_WORDS.includes(t) || /^\/allowed off (?:all|[1-9]\d?)$/.test(t)) ? t : null;
}
const BRAIN_WORD_MIN_UP_MS = 10 * 60000;
// With Sparkie's own model not answering, an owner's one-line message starting with "/" that isn't a word gets /help
// instead of a failed turn. With it answering, or chat routed to another model, such a message goes to Sparkie.
async function nearMissWord(text) {
  const t = String(text).trim();
  if (!t.startsWith('/') || t.length > 40 || t.includes('\n') || chatTarget()?.kind !== 'main') return null;
  // (longer than the status check's own 3-second look at the brain, so a frozen brain still counts as not answering)
  const late = Symbol('late');
  const m = await Promise.race([recentMain(), sleep(6000).then(() => late)]).catch(() => null);
  // A look that didn't come back in time means Sparkie's model isn't answering promptly either (a frozen brain holds the
  // look's own request): /help, which is a fine answer to a mistyped word even when the model was only slow.
  if (m === late) return '/help';
  return m?.configured && !(m.state === 'running' && m.healthy) ? '/help' : null;
}
// Where Spark Console itself runs (its settings file is there), in words.
const consoleSparkWords = () => { const n = NODES.find(x => x.host === 'local'); return n ? `on ${sparkName(n)}` : 'on the Spark that runs Spark Console'; };

// Where things stand, from Spark Console's own record: no model call, never waits on another Spark (the brain check is
// capped at 8 seconds). Telegram's /status is the same text.
async function statusText() {
  let brain = 'not checked';
  try {
    const m = await Promise.race([recentMain(), sleep(8000).then(() => null)]);
    brain = !m ? 'not checked (slow to answer)' : !m.configured ? 'not set up' : !m.online ? 'not checked (its Spark didn’t answer)'
      : m.state !== 'running' ? 'stopped' : m.healthy ? 'running, and its server responds' : 'running, but its server doesn’t respond';
  } catch {}
  const chat = chatTarget(), s = agentSettings();
  const online = NODES.filter(n => !knownOffline(n)).map(n => sparkName(n));
  const running = [...jobs.values()].filter(j => j.status === 'running').length;
  // What is waiting on the owner (20-needs.mjs): the same lines as fleet_status's needsOwner, right after Sparkie's own.
  const needs = needsLines();
  // (the owner's requests Sparkie is carrying on with, and their counts so far from the journal: 14-tasks.mjs, E7)
  let tasks = [];
  try { tasks = tasksNowLines(); } catch {}
  return maskSecrets([`Sparkie: ${brain}.`,
    chat?.kind === 'endpoint' ? `Sparkie’s chat runs on ${String(chat.title || chat.model).slice(0, 80)} right now, not on its own model.${chat.node && nodeById(chat.node) && knownOffline(nodeById(chat.node)) ? ' Its Spark isn’t reachable, so chat can’t answer.' : ''}` : null,
    needs.length ? `Needs you:\n${needs.map(t => `- ${t}`).join('\n')}` : 'Needs you: nothing.',
    `Sparks online: ${online.length ? online.join(', ') : 'none'}.`, `Operations running: ${running}.`, `Spark Console build ${BUILD}.`,
    `Agents’ changes: ${s.halted ? (s.autoPaused ? 'paused automatically' : 'paused') : 'on'}.`,
    `Open to the internet: ${funnelOn === null ? 'not known' : funnelOn ? 'yes' : 'no'}.`,
    tasks.length ? `Requests Sparkie is carrying on with:\n${tasks.map(t => `- ${t}`).join('\n')}` : null].filter(Boolean).join('\n'));
}

function pauseWord(via) {
  const was = agentSettings(), already = was.halted && !was.autoPaused;
  // (its note outside the state first, then the save: 22-putback.mjs; a note that waits is said below)
  const unnoted = putBackRemoval({ kind: 'paused' }, () => setAgentSettings({ halted: true, autoPaused: false }));
  // (an open dangerous ask closes: 20-danger.mjs)
  dangerPaused();
  audit({ via, actor: 'owner', action: 'agent-settings', args: { halted: true, word: '/pause' }, ok: true });
  if (!already) fleetEvent({ type: 'operation', operation: 'agents paused', status: 'completed', by: 'owner' });
  // (on Telegram: no file path, and it's never resumed from there, R32)
  return `${already ? 'Already paused.' : 'Paused.'} Operations started by Sparkie, an agent, Telegram or the API stop at their next step and put back what they changed. Models already running stay up. Self-healing is off while paused.
${via === 'telegram' ? 'To resume: in Spark Console, your account menu → Agents and Telegram, with your passkey. It can’t be resumed from Telegram.' : `To resume: your account menu → Agents and Telegram, with your passkey. Or by hand ${consoleSparkWords()}: set "halted": false in ${SETTINGS_FILE}.`}${unnoted ? `\n${unnoted}` : ''}`;
}

async function restartWord(via) {
  const chat = chatTarget();
  if (chat?.kind === 'endpoint') return `Sparkie’s chat runs on ${String(chat.title || chat.model).slice(0, 80)} right now, so restarting Sparkie’s own model wouldn’t help. Nothing was changed.`;
  if (!MAIN) return 'Sparkie’s model isn’t set up. Nothing was changed.';
  const busyWords = `Sparkie’s model is being started, stopped or switched, or something else is changing on ${sparkName(mainNode() || { id: MAIN.node })}, right now. Nothing was changed. /status shows where it stands.`;
  if (brainRestarting) return 'Sparkie’s model is already restarting. /status shows when its server responds.';
  if (mainBusy() || busySparks.has(MAIN.node)) return busyWords;
  const m = await mainStatus().catch(() => null);
  if (!m?.online) return `Couldn’t check Sparkie’s model on ${sparkName(mainNode() || { id: MAIN.node })}. Nothing was changed.`;
  const x = { spark: MAIN.node, container: MAIN.container };
  // Not running: stopped (exited, created), or gone from Docker (a failed switch, or removed by hand). The saved setup
  // starts again through the same job as the page's Start, which removes the old container first (a stopped one keeps
  // its /tmp, where a stale rendezvous file can hang the load: review, 2026-11-12), and everything else on that Spark
  // keeps running (the word never stops anything to make room).
  if (m.state !== 'running') {
    const gone = m.state === 'missing';
    let job;
    try {
      const keep = (await mainPlan()).steps.filter(s => s.kind === 'stop').map(s => s.container);
      job = claimed([MAIN.node], 'starting Sparkie’s model', () => newJob('main-start', { node: MAIN.node, model: MAIN.title || MAIN.served }));
      runJob(job, j => startMain(j, keep));
    } catch (e) { return `Sparkie’s model ${gone ? 'is gone from Docker' : 'isn’t running'}, and it can’t be started right now: ${String(e.message).split('\n')[0].slice(0, 300)} Nothing was changed.`; }
    audit({ via, actor: 'owner', action: 'start_sparkie', args: { ...x, word: '/restart sparkie' }, ok: true, outcome: 'started', operation: job.id });
    return `Sparkie’s model ${gone ? 'was gone from Docker' : 'wasn’t running'}, so it’s starting again from its saved setup (${MAIN.title || MAIN.served}). Nothing else on ${sparkName(mainNode() || { id: MAIN.node })} is stopped for it. It takes a few minutes to load; /status shows when its server responds.`;
  }
  // Running: Docker's own start time, so the limit holds across a console restart: a model still loading isn't restarted.
  const started = Date.parse(m.startedAt), upMs = Number.isFinite(started) ? Date.now() - started : 0, mins = Math.max(1, Math.round(upMs / 60000));
  if (upMs < BRAIN_WORD_MIN_UP_MS) return `${Number.isFinite(started) ? `Sparkie’s model started ${mins} minute${mins === 1 ? '' : 's'} ago and may still be loading` : 'Docker didn’t say when Sparkie’s model started, so it may still be loading'}; a restart would make that longer. Nothing was changed. Try again once it has run 10 minutes.`;
  if (brainRestarting) return 'Sparkie’s model is already restarting. /status shows when its server responds.';
  if (mainBusy() || busySparks.has(MAIN.node)) return busyWords;
  fleetEvent({ type: 'operation', operation: 'Sparkie’s model restarting', status: 'started', by: 'owner', spark: x.spark, container: x.container });
  // A restart takes a few minutes: it goes on after this answer.
  restartBrain().then(r => {
    if (!r) return;
    audit({ via, actor: 'owner', action: 'restart_sparkie', args: { ...x, word: '/restart sparkie' }, ok: r.code === 0, ...(r.code ? { error: maskSecrets((r.err || r.out).slice(0, 300)) } : {}) });
    fleetEvent({ type: 'operation', operation: 'Sparkie’s model restarted', status: r.code ? 'failed' : 'completed', by: 'owner', spark: x.spark, container: x.container });
  }).catch(e => console.error(`Restarting Sparkie’s model: ${e.message}`));
  return 'Restarting Sparkie’s model. It takes a few minutes to load again; /status shows when its server responds.';
}

// /stop: Sparkie's answer in this chat ends, and so does its carrying on with that request (stopTurn, 14-chats.mjs), and
// the chat's box goes (boxStop, 21-box.mjs). It never cancels an operation and never stops a model.
async function stopWord(conv) {
  // (a dangerous ask this chat asked closes too: 20-danger.mjs; and the chat's box goes, said once its removal is seen
  // or not: 21-box.mjs)
  const asked = dangerStopped(conv), turn = Boolean(conv && stopTurn(conv)), box = conv ? await boxStop(conv) : null;
  const gone = !box ? '' : box.removed ? ` This chat’s box on ${box.at} was removed, with its folder.`
    : ` This chat’s box on ${box.at} couldn’t be removed just now (${box.why}); it ends by itself at ${box.until}, and /stop here tries again.`;
  if (turn) return `Stopped. Sparkie’s answer in this chat ends here, and it won’t carry on with that request.${gone} Operations already started keep running and post their results here. No model was stopped. To stop an operation, ask Sparkie to cancel it.`;
  if (asked) return `Stopped. The ask in this chat that waited for your answer is closed, and nothing was run.${gone}`;
  if (box) return `Sparkie isn’t answering in this chat and has nothing to carry on with.${gone} Operations and models are as they were.`;
  return 'Sparkie isn’t answering in this chat and has nothing to carry on with, so there was nothing to stop. Operations and models are as they were.';
}

// Where every install puts the by-hand way back (deploy/go-back.sh, deploy/RECOVERY.txt) and the rebuild steps
// (deploy/REBUILD.txt).
const BY_HAND_DIR = `${homedir()}/.local/share/spark-console`;
// /undo update: the page's Undo update, typed. It is the undo_update action through runAction as the page, so that
// action's own guard decides (R31): on the owner's tailnet it runs; a device signed in over the internet gets the
// owner-only button, pressed here with the passkey. It is not a word on Telegram.
async function undoWord(viewer, conv) {
  let asked = null;
  try {
    const out = await runAction('undo_update', viewer, {}, { via: 'page', actor: 'owner', request: '/undo update', chat: conv.id, conv: conv.id, canChange: true, onQuestion: q => { asked = q; } });
    if (asked) return { reply: asked.question, choices: sparkieMessageChoices(asked) };
    return { reply: out?.note || 'Going back a build. Spark Console restarts in a moment.' };
  } catch (e) { return { reply: e.message }; }
}

// /undo: this chat's last change put back (undo_last_change: a command's files on a Spark, or a model change), typed.
// The owner's own word, answered by code on the page and in the paired Telegram chat, so it works while changes are
// paused (ownerWord, runAction's pause): a pause must never keep the owner from putting a change back (A7c).
async function undoChangeWord(viewer, conv, via) {
  let asked = null;
  try {
    const out = await runAction('undo_last_change', viewer, {}, { via, actor: 'owner', request: '/undo', chat: conv.id, conv: conv.id, canChange: true, ownerWord: true,
      ...(via === 'telegram' ? { channel: 'telegram', from: `telegram:${tgPaired()?.userId ?? '?'}` } : {}), onQuestion: q => { asked = q; } });
    if (asked) return { reply: asked.question, choices: sparkieMessageChoices(asked) };
    return { reply: out?.note || 'Undoing the last change.' };
  } catch (e) { return { reply: e.message }; }
}

function helpWord() {
  const lines = ['These work even when Sparkie can’t answer. Type the word alone:',
    '/status: where things stand, from Spark Console’s own record',
    '/pause: pause agents’ changes (resume in your account menu → Agents and Telegram, with your passkey)',
    '/restart sparkie: restart Sparkie’s model when it’s stuck, or start it again when it’s stopped',
    '/stop: end Sparkie’s answer in this chat and its carrying on; operations and models keep running',
    '/undo: put back this chat’s last change (works while changes are paused)',
    '/undo update: go back to the build from before the last update (Spark Console restarts; signed in from the internet, it asks for your passkey)',
    '/allowed: what is always allowed in your chats; /allowed off 2 takes one away, /allowed off all every one',
    '/putback: put back the newest change made inside the lock-out net, unless it was kept (21-net.mjs)',
    '/help: this list'];
  lines.push('', '/key NAME and then the key (HF_TOKEN, say, or GITHUB): give Sparkie a key once; it is kept by name and never shown. A heartbeat address from Healthchecks.io can be pasted as it is.');
  lines.push('', 'By hand, in a terminal:');
  if (MAIN) lines.push(`  restart Sparkie’s model (on ${sparkName(mainNode() || { id: MAIN.node })}): ${brainRestartCommand()}`);
  lines.push(`  go back a build (${consoleSparkWords()}): bash ${BY_HAND_DIR}/go-back.sh (other by-hand steps: ${BY_HAND_DIR}/RECOVERY.txt)`);
  lines.push(`  bring ${consoleSparkWords().replace(/^on /, '')} back after its disk is lost: deploy/REBUILD.txt on GitHub (a copy: ${BY_HAND_DIR}/REBUILD.txt)`);
  lines.push(`  resume agents’ changes (${consoleSparkWords()}): set "halted": false in ${SETTINGS_FILE}`);
  return lines.join('\n');
}

// The page's chat route calls this for the owner's own chat (never one that carries `agent`). The answer comes back in
// the same event stream as Sparkie's, so the page needs nothing new.
async function answerOwnerWord(res, conv, word, via, typed = null, viewer = null) {
  const undo = word === '/undo update' ? await undoWord(viewer, conv) : word === '/undo' ? await undoChangeWord(viewer, conv, 'page') : null;
  const reply = undo ? undo.reply : word === '/status' ? await statusText() : word === '/pause' ? pauseWord(via)
    : word === '/restart sparkie' ? await restartWord(via) : word === '/stop' ? await stopWord(conv) : word.startsWith('/allowed') ? allowedWord(word, via) : word === '/putback' ? await netPutbackWord() : helpWord();
  const head = typed ? `${String(typed).trim().slice(0, 40)}\nThat isn’t one of the words, and Sparkie’s model isn’t answering.` : word;
  const message = { role: 'assistant', content: `${maskSecrets(head)}\n${maskSecrets(reply)}`, createdAt: new Date().toISOString(), notice: true, word: true,
    ...(undo?.choices?.length ? { choices: undo.choices } : {}) };
  // (A full chat still gets the answer; it just isn't saved there.)
  if (conv.messages.length < LIMITS.messages) {
    conv.messages.push(message);
    conv.updatedAt = message.createdAt;
    saveChats();
  }
  res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache, no-transform', 'x-accel-buffering': 'no' });
  res.write(`data: ${JSON.stringify({ type: 'started' })}\n\n`);
  res.end(`data: ${JSON.stringify({ type: 'done', message })}\n\n`);
}
/* ───────── the go-ahead: yes to one command, or one kind, for the rest of a task (A9a), or always (A9b) ───────── */
// Area: features        Rules: R65        Tests: ahead.test.mjs, allowed.test.mjs
// Owns: none
// Timers: none        Wakes: none
// On a change's button (21-ladder.mjs workAsk) the owner may answer "Run it, and don't ask again for this task: …".
// For the rest of that request (the turns that carry it on), a command of that kind then runs without a button: the
// kind is a plain change's tool (the program the sorter resolved, 20-sort.mjs), its place (the folder its places are
