    res = await fetch(`${TG_API}/bot${token}/${method}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), redirect: 'error', signal: ctl.signal });
    data = await res.json().catch(() => null);
