const PROVE_LOCK_AT = `${ALL_LOCAL ? '"$HOME/.rehearsal"' : ''}/run/spark-console/prove.lock`;
// A look's seconds: 30 (the helper allows 60, but a tool call has 50 seconds in chat and at the agent door, and the
